solutions = []
for x in range(1, 6):
    for y in range(x, 6):
        for z in range(y, 6):
            lhs = x**3 + y**3 + z**3
            rhs = x**2 * y**2 * z**2
            if lhs == rhs:
                solutions.append((x, y, z))

print("Found solutions:", solutions)

def check_solution(x, y, z):
    return x**3 + y**3 + z**3 == x**2 * y**2 * z**2

print(f"Checking (1, 2, 3): {check_solution(1, 2, 3)}")
